from PIL import Image
for p in ['/tmp/settings_bg.png','/tmp/numbers_bg.png','/tmp/settings_current.png','/tmp/numbers_current.png']:
    im=Image.open(p).convert('RGB')
    # scan top-left 100x40 for strongly red, yellow, green pixels
    reds=[]; yellows=[]; greens=[]
    for y in range(0,40):
        for x in range(0,100):
            r,g,b=im.getpixel((x,y))
            if r>180 and g<130 and b<130: reds.append((x,y,(r,g,b)))
            if r>200 and g>150 and b<120: yellows.append((x,y,(r,g,b)))
            if g>120 and r<130 and b<130: greens.append((x,y,(r,g,b)))
    print(p, 'reds',len(reds), reds[:3], 'yellows',len(yellows), yellows[:3], 'greens',len(greens), greens[:3])
PY"

